<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('Faculty');check_csrf();$u=current_user();$f=db()->prepare('SELECT id FROM faculty WHERE user_id=?');$f->execute([$u['id']]);$fid=(int)$f->fetchColumn();$subjects=db()->prepare('SELECT s.id,s.name,s.code FROM subjects s JOIN faculty_subjects fs ON fs.subject_id=s.id WHERE fs.faculty_id=?');$subjects->execute([$fid]);$subjects=$subjects->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$subject=(int)$_POST['subject_id'];$date=$_POST['date'];$division=(int)$_POST['division_id'];$mode=$_POST['mode']??'manual';$code=secure_random(6);try{db()->beginTransaction();$q=db()->prepare('INSERT INTO attendance_sessions(subject_id,faculty_id,date,start_time,end_time,division_id,mode,class_code) VALUES(?,?,?,CURTIME(),CURTIME(),?,?,?) ON DUPLICATE KEY UPDATE mode=VALUES(mode),class_code=VALUES(class_code)');$q->execute([$subject,$fid,$date,$division,$mode,$code]);$sid=(int)db()->lastInsertId();if(!$sid){$s=db()->prepare('SELECT id FROM attendance_sessions WHERE subject_id=? AND date=? AND division_id=?');$s->execute([$subject,$date,$division]);$sid=(int)$s->fetchColumn();}$st=db()->prepare('SELECT id FROM students WHERE division_id=? AND status="active"');$st->execute([$division]);$ins=db()->prepare('INSERT INTO attendance(session_id,student_id,status,remarks) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),remarks=VALUES(remarks)');foreach($st as $row){$status=$_POST['status_'.$row['id']]??'Absent';$ins->execute([$sid,$row['id'],$status,$_POST['remarks_'.$row['id']]??'']);}db()->commit();AuditService::log('MARK','attendance',$sid,'Attendance session');$_SESSION['flash']=['success','Attendance saved'];}catch(Throwable $e){db()->rollBack();$_SESSION['flash']=['danger',$e->getMessage()];}redirect('attendance.php');}$divs=db()->query('SELECT * FROM divisions ORDER BY name')->fetchAll();$selected=(int)($_GET['division_id']??($divs[0]['id']??0));$students=[];if($selected){$q=db()->prepare('SELECT id,enrollment_no,user_id FROM students WHERE division_id=? AND status="active"');$q->execute([$selected]);$students=$q->fetchAll();}$names=[];if($students){$ids=implode(',',array_map('intval',array_column($students,'user_id')));$names=$ids?db()->query("SELECT id,name FROM users WHERE id IN ($ids)")->fetchAll(PDO::FETCH_KEY_PAIR):[];}page_top('Smart Attendance Studio');flash();?><div class='card p-4'><form method='get' class='row g-3'><div class='col-md-4'><label class='form-label'>Subject</label><select class='form-select' name='subject_id'><?php foreach($subjects as $s):?><option value='<?=e($s['id'])?>'><?=e($s['code'].' · '.$s['name'])?></option><?php endforeach;?></select></div><div class='col-md-3'><label>Division</label><select class='form-select' name='division_id'><?php foreach($divs as $d):?><option value='<?=e($d['id'])?>' <?=($selected==$d['id']?'selected':'')?>><?=e($d['name'])?></option><?php endforeach;?></select></div><div class='col-md-3'><label>Date</label><input type='date' class='form-control' name='date' value='<?=e(date('Y-m-d'))?>'></div><div class='col-md-2 align-self-end'><button class='btn btn-outline-primary w-100'>Load</button></div></form></div><form method='post' class='card p-4 mt-3'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><input type='hidden' name='subject_id' value='<?=e((int)($_GET['subject_id']??($subjects[0]['id']??0)))?>'><input type='hidden' name='division_id' value='<?=e($selected)?>'><input type='hidden' name='date' value='<?=e($_GET['date']??date('Y-m-d'))?>'><input type='hidden' name='mode' value='manual'><div class='table-responsive'><table class='table'><thead><tr><th>Enrollment</th><th>Student</th><th>Attendance</th><th>Remarks</th></tr></thead><tbody><?php foreach($students as $st):?><tr><td><?=e($st['enrollment_no'])?></td><td><?=e($names[$st['user_id']]??'Student')?></td><td><select name='status_<?=e($st['id'])?>' class='form-select'><option>Present</option><option>Absent</option><option>Late</option><option>Leave</option></select></td><td><input name='remarks_<?=e($st['id'])?>' class='form-control'></td></tr><?php endforeach;?></tbody></table></div><button class='btn btn-primary'>Save Attendance</button></form><?php page_bottom();